insert into public.ingredientes (inci, nombre_es, funciones, restriccion, rango_uso, que_es, origen, fuente, categoria, precauciones, parte_usada, verificado) values
  ('Prunus Amygdalus Dulcis Oil', 'Aceite de almendras dulces', array['Emoliente', 'Nutritivo']::text[], null, '5-100% según el producto', 'Aceite ligero de tacto sedoso, rico en ácido oleico (~62-75%) y linoleico. El emoliente vegetal más versátil para piel, masaje y desmaquillantes.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Evitar si hay alergia a frutos secos', null, false),
  ('Prunus Armeniaca Kernel Oil', 'Aceite de damasco (carozo de damasco)', array['Emoliente']::text[], null, '5-100%', 'Aceite ligero de absorción rápida, parecido al de almendras, con ácido oleico y linoleico. Se usa en piel delicada y rostro.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Evitar si hay alergia a frutos secos o a las rosáceas', null, false),
  ('Persea Gratissima Oil', 'Aceite de palta (aguacate)', array['Emoliente', 'Nutritivo']::text[], null, '5-50%', 'Aceite denso, con ácido oleico y una fracción insaponificable rica en esteroles y tocoferoles. Muy nutritivo.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Pesado en rostro graso: mejor para cuerpo, manos y cabello', null, false),
  ('Simmondsia Chinensis Seed Oil', 'Aceite de jojoba', array['Emoliente', 'Acondicionador de piel']::text[], null, '5-100%', 'Técnicamente una cera líquida (ésteres de cera), muy estable y que no se enrancia con facilidad. Su estructura se parece al sebo de la piel.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', null, null, false),
  ('Argania Spinosa Kernel Oil', 'Aceite de argán', array['Emoliente', 'Antioxidante', 'Nutritivo']::text[], null, '2-100%', 'Rico en ácido oleico y linoleico, con tocoferoles. Nutritivo y de buena extensión, usado en piel madura y cabello.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', null, null, false),
  ('Rosa Rubiginosa Seed Oil', 'Aceite de rosa mosqueta', array['Emoliente', 'Regenerador', 'Antioxidante']::text[], null, '2-20% o puro', 'Aceite de semilla rico en ácidos linoleico y alfa-linolénico. Se usa en piel seca, marcas y piel madura. Se oxida con facilidad.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Termosensible y de vida corta: guardar refrigerado, agregar bajo 38 °C', null, false),
  ('Rosa Canina Fruit Oil', 'Aceite de escaramujo (rosa canina)', array['Emoliente', 'Regenerador', 'Antioxidante']::text[], null, '2-20% o puro', 'Aceite de escaramujo, de composición parecida a la mosqueta. Rico en ácidos grasos poliinsaturados.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Se enrancia con rapidez: refrigerar', null, false),
  ('Helianthus Annuus Seed Oil', 'Aceite de girasol', array['Emoliente']::text[], null, '5-100%', 'Rico en linoleico (el común) o en oleico (el alto oleico, más estable). Económico y versátil para macerados y aceites de masaje.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'El común se enrancia rápido: prefiere el alto oleico', null, false),
  ('Olea Europaea Fruit Oil', 'Aceite de oliva', array['Emoliente', 'Nutritivo']::text[], null, '5-100%', 'Con ~55-80% de ácido oleico y trazas de escualeno y polifenoles. Nutritivo y de tacto rico. Base clásica de jabones de castilla y bálsamos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Pesado en rostro graso. El virgen extra tiene aroma marcado', null, false),
  ('Cocos Nucifera Oil', 'Aceite de coco', array['Emoliente', 'Acondicionador capilar']::text[], null, '5-30%', 'Rico en ácido láurico (~45-52%). Sólido bajo ~24 °C. Muy estable, con actividad antimicrobiana propia del láurico. Base de jabones y desodorantes.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Puede ser comedogénico en rostro de piel grasa', null, false),
  ('Caprylic/Capric Triglyceride', 'Aceite de coco fraccionado (triglicérido caprílico/cáprico)', array['Emoliente', 'Disolvente', 'Vehículo']::text[], null, '2-100%', 'Fracción líquida de ácidos grasos de cadena media del coco. Ligero, sin olor, muy estable y de absorción rápida. Disuelve aceites esenciales y activos liposolubles.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', null, null, false),
  ('Ricinus Communis Seed Oil', 'Aceite de ricino', array['Emoliente', 'Humectante', 'Brillo']::text[], null, '5-15%', '~90% ácido ricinoleico, un ácido graso hidroxilado único. Espesa los aceites y da brillo; imprescindible en labiales.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Sobre ~20% se siente pegajoso. La semilla es tóxica pero el aceite refinado es seguro', null, false),
  ('Sesamum Indicum Seed Oil', 'Aceite de sésamo', array['Emoliente', 'Antioxidante']::text[], null, '5-100%', 'Con ácidos oleico y linoleico y antioxidantes propios (sesamol, sesamina) que lo hacen estable. Aceite clásico del masaje ayurvédico.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Alérgeno frecuente. Sin refinar tiene aroma marcado', null, false),
  ('Vitis Vinifera Seed Oil', 'Aceite de semilla de uva', array['Emoliente']::text[], null, '5-100%', 'Muy ligero, con ~65-75% de ácido linoleico. Se absorbe rápido y deja tacto seco: buen aliado de pieles mixtas y grasas.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Se enrancia con facilidad: guardar frío y con vitamina E', null, false),
  ('Corylus Avellana Seed Oil', 'Aceite de avellana', array['Emoliente']::text[], null, '5-100%', 'Con ~70-80% de ácido oleico. Ligero, de absorción rápida y tacto seco, usado en piel mixta.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Evitar si hay alergia a frutos secos', null, false),
  ('Macadamia Ternifolia Seed Oil', 'Aceite de macadamia', array['Emoliente', 'Nutritivo']::text[], null, '5-100%', 'Rico en ácido palmitoleico (~15-25%), presente en el sebo de la piel joven. Nutritivo, de buena extensión y muy estable.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Evitar si hay alergia a frutos secos', null, false),
  ('Oenothera Biennis Oil', 'Aceite de onagra', array['Emoliente', 'Calmante']::text[], null, '2-20%', '~70% de ácido linoleico y 8-10% de ácido gamma-linolénico (GLA). Se usa en piel seca y reactiva.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Se oxida rápido: refrigerar', null, false),
  ('Borago Officinalis Seed Oil', 'Aceite de borraja', array['Emoliente', 'Calmante']::text[], null, '2-20%', 'Una de las fuentes más ricas de ácido gamma-linolénico (~20-25%). Se usa en piel seca y madura.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Se oxida rápido: refrigerar', null, false),
  ('Plukenetia Volubilis Seed Oil', 'Aceite de sacha inchi', array['Emoliente', 'Nutritivo']::text[], null, '2-20%', 'Semilla amazónica con ~45-50% de ácido alfa-linolénico (omega-3) y ~35% de linoleico. Muy ligero.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Se oxida muy rápido: frasco oscuro, refrigerado y vida corta', null, false),
  ('Calophyllum Inophyllum Seed Oil', 'Aceite de tamanu', array['Emoliente', 'Cicatrizante']::text[], null, '1-10%', 'Aceite verde oscuro, viscoso y de aroma fuerte, tradicional de la Polinesia. Se usa en cicatrices y piel dañada; se le atribuye acción cicatrizante y hay estudios preliminares.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Olor y color intensos. Haz prueba de parche; evitar si hay alergia a frutos secos', null, false),
  ('Carthamus Tinctorius Seed Oil', 'Aceite de cártamo', array['Emoliente']::text[], null, '5-100%', 'Muy ligero. Hay variedad rica en linoleico (más inestable) y rica en oleico (más estable).', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Elegir la variedad alto oleico para mayor estabilidad', null, false),
  ('Linum Usitatissimum Seed Oil', 'Aceite de linaza (lino)', array['Emoliente']::text[], null, '1-10%', 'Muy rico en ácido alfa-linolénico (~50-60%). Se seca (polimeriza) con rapidez.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Se enrancia muy rápido: refrigerar y usar poco', null, false),
  ('Cannabis Sativa Seed Oil', 'Aceite de semilla de cáñamo', array['Emoliente', 'Calmante']::text[], null, '2-20%', 'Rico en linoleico y alfa-linolénico, con algo de gamma-linolénico. No contiene cannabinoides en cantidad relevante.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Se oxida rápido: refrigerar. Revisa la normativa de tu país', null, false),
  ('Camellia Oleifera Seed Oil', 'Aceite de camelia', array['Emoliente']::text[], null, '5-100%', 'Rico en ácido oleico (~75-85%), ligero y de absorción rápida. Usado tradicionalmente en cabello y piel en Asia.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', null, null, false),
  ('Gevuina Avellana Seed Oil', 'Aceite de avellano chileno (gevuina)', array['Emoliente', 'Antioxidante']::text[], null, '5-100%', 'Aceite de semilla del avellano chileno, rico en ácido oleico y palmitoleico. Ligero, de buena extensión; ingrediente de la flora nativa.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Evitar si hay alergia a frutos secos', null, false),
  ('Ugni Molinae Seed Oil', 'Aceite de semilla de murtilla', array['Emoliente', 'Antioxidante']::text[], null, '2-20%', 'Aceite de la semilla de la murtilla, rico en ácidos grasos poliinsaturados y tocoferoles. Producto emergente de la flora nativa.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Información técnica limitada: pedir ficha al proveedor', null, false),
  ('Rubus Idaeus Seed Oil', 'Aceite de semilla de frambuesa', array['Emoliente', 'Antioxidante']::text[], null, '2-20%', 'Rico en linoleico y alfa-linolénico, con tocoferoles y carotenoides. Se usa en cremas para piel seca.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Se oxida rápido: refrigerar', null, false),
  ('Punica Granatum Seed Oil', 'Aceite de semilla de granada', array['Emoliente', 'Antioxidante']::text[], null, '1-10%', 'Rico en ácido púnico (un ácido graso conjugado poco común). Se usa en piel madura.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Se oxida rápido: refrigerar', null, false),
  ('Hippophae Rhamnoides Fruit Oil', 'Aceite de espino amarillo (sea buckthorn)', array['Emoliente', 'Antioxidante', 'Colorante']::text[], null, '1-5%', 'Aceite naranja intenso, rico en carotenoides y ácido palmitoleico. Se usa en piel dañada o seca.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Tiñe la piel y la ropa. Haz prueba de parche', null, false),
  ('Oryza Sativa Bran Oil', 'Aceite de salvado de arroz', array['Emoliente', 'Antioxidante']::text[], null, '5-100%', 'Contiene gamma-orizanol y tocotrienoles, antioxidantes. Ligero y estable.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', null, null, false),
  ('Glycine Soja Oil', 'Aceite de soya', array['Emoliente']::text[], null, '5-100%', 'Aceite rico en linoleico, económico y ligero. Base común de cremas y macerados.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Evitar si hay alergia a la soya', null, false),
  ('Zea Mays Germ Oil', 'Aceite de germen de maíz', array['Emoliente']::text[], null, '5-100%', 'Rico en linoleico y tocoferoles. Ligero y económico.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', null, null, false),
  ('Sclerocarya Birrea Seed Oil', 'Aceite de marula', array['Emoliente', 'Antioxidante']::text[], null, '5-100%', 'Rico en ácido oleico (~70-78%) y antioxidantes. Ligero, de absorción rápida y estable.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Evitar si hay alergia a frutos secos', null, false),
  ('Adansonia Digitata Seed Oil', 'Aceite de baobab', array['Emoliente', 'Nutritivo']::text[], null, '5-100%', 'Con ácidos oleico, linoleico y palmítico y vitaminas liposolubles. Nutritivo y de buena extensión.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', null, null, false),
  ('Nigella Sativa Seed Oil', 'Aceite de comino negro', array['Emoliente', 'Antiinflamatorio']::text[], null, '1-10%', 'Contiene timoquinona. De aroma fuerte; se estudia por su actividad antiinflamatoria y antimicrobiana.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Puede irritar o sensibilizar la piel. Haz prueba de parche', null, false),
  ('Moringa Oleifera Seed Oil', 'Aceite de moringa (ben)', array['Emoliente']::text[], null, '5-100%', 'Rico en ácido oleico (~70%) y muy estable. Ligero y de absorción rápida.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', null, null, false),
  ('Prunus Persica Kernel Oil', 'Aceite de carozo de durazno', array['Emoliente']::text[], null, '5-100%', 'Ligero, parecido al de damasco y al de almendras. Rico en oleico y linoleico.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Evitar si hay alergia a frutos secos o a las rosáceas', null, false),
  ('Daucus Carota Sativa Root Extract', 'Macerado oleoso de zanahoria', array['Emoliente', 'Antioxidante', 'Colorante']::text[], null, '5-50%', 'Zanahoria macerada en aceite: aporta betacarotenos y color. Se usa en bronceadores y cremas nutritivas.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Tiñe la piel. No protege del sol por sí solo', null, false),
  ('Squalane', 'Escualano', array['Emoliente', 'Acondicionador de piel']::text[], null, '1-30%', 'Hidrocarburo saturado de origen vegetal (oliva, caña de azúcar) o de tiburón. Ultraligero, estable y no comedogénico; refuerza la barrera cutánea.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Elige el de origen vegetal', null, false),
  ('Squalene', 'Escualeno', array['Emoliente', 'Antioxidante']::text[], null, '1-5%', 'Hidrocarburo insaturado presente en el sebo humano y en el aceite de oliva. Se oxida con facilidad; por eso se usa más el escualano.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Aceites vegetales', 'Se oxida: refrigerar y agregar antioxidante', null, false),
  ('Niacinamide', 'Niacinamida (vitamina B3)', array['Seborregulador', 'Antiedad', 'Aclarante', 'Acondicionador de piel']::text[], null, '2-5% (hasta 10%)', 'El activo multiuso. Mejora la barrera cutánea, regula el sebo y afina el aspecto del poro, y atenúa manchas al frenar la transferencia de melanina a los queratinocitos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Más de 10% puede enrojecer en piel sensible. Estable en pH 5-7', null, false),
  ('Ascorbic Acid', 'Vitamina C (ácido ascórbico)', array['Antioxidante', 'Aclarante', 'Antiedad']::text[], null, '5-15% a pH menor de 3.5', 'Forma pura de la vitamina C. Antioxidante potente y cofactor de la síntesis de colágeno; muy inestable al aire, la luz y el agua.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Se oxida y se vuelve amarillo/marrón: frasco oscuro, poca cantidad, preferir uso nocturno y protector solar de día', null, false),
  ('Sodium Ascorbyl Phosphate', 'Fosfato ascorbil de sodio', array['Antioxidante', 'Aclarante']::text[], null, '1-5% a pH 6-7', 'Derivado estable de la vitamina C, soluble en agua. Más suave que el ácido ascórbico.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
  ('Magnesium Ascorbyl Phosphate', 'Fosfato ascorbil de magnesio', array['Antioxidante', 'Aclarante']::text[], null, '1-5% a pH 6-7', 'Derivado estable de la vitamina C, soluble en agua y bien tolerado.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
  ('Ascorbyl Glucoside', 'Ascorbil glucósido', array['Antioxidante', 'Aclarante']::text[], null, '2-5%', 'Vitamina C unida a glucosa, estable y suave. Se libera con una enzima de la piel.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
  ('Tocopherol', 'Vitamina E (tocoferol)', array['Antioxidante', 'Vitamina']::text[], null, '0.1-1% como antioxidante de la fórmula', 'Antioxidante liposoluble. Protege los aceites del enranciamiento y la piel del estrés oxidativo.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'No es un conservante microbiano', null, false),
  ('Tocopheryl Acetate', 'Acetato de tocoferilo', array['Antioxidante', 'Vitamina']::text[], null, '0.5-2%', 'Forma estable y esterificada de la vitamina E, más resistente a la oxidación.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
  ('Retinyl Palmitate', 'Palmitato de retinilo (vitamina A)', array['Antiedad', 'Vitamina']::text[], null, '0.1-1%', 'Éster de la vitamina A, la forma más suave. Se convierte en retinol en la piel de forma gradual.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Evitar en embarazo. Fotosensibiliza: usar de noche', null, false),
  ('Bakuchiol', 'Bakuchiol', array['Antiedad']::text[], null, '0.5-1%', 'Compuesto vegetal usado como alternativa al retinol. Un ensayo clínico aleatorizado comparó bakuchiol 0.5% con retinol 0.5%: mejoró arrugas y pigmentación de forma similar y con menos irritación.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Liposoluble', null, false),
  ('Salicylic Acid', 'Ácido salicílico (BHA)', array['Queratolítico', 'Exfoliante', 'Antimicrobiano']::text[], 'UE: 2% en productos que se dejan (3% en capilares que se enjuagan); no para menores de 3 años. Verifica la normativa de tu país', '0.5-2% a pH 3-4', 'Beta-hidroxiácido liposoluble que entra en el poro y disuelve el tapón de sebo y células muertas. Base de los productos para piel grasa y con acné.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Evitar en embarazo y en alergia a la aspirina. Fotosensibiliza: protector solar de día', null, false),
  ('Glycolic Acid', 'Ácido glicólico (AHA)', array['Exfoliante', 'Queratolítico']::text[], null, '5-10% a pH 3.5-4', 'AHA de molécula pequeña: penetra con facilidad, exfolia y renueva. El más potente (e irritante) de los AHA de uso cosmético.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Fotosensibiliza: uso nocturno y protector solar de día', null, false),
  ('Lactic Acid', 'Ácido láctico (AHA)', array['Exfoliante', 'Regulador de pH', 'Humectante']::text[], null, '2-10% a pH 3.5-4; 0.1-0.5% como regulador', 'AHA más suave que el glicólico; además humecta y regula el pH de la fórmula.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Fotosensibiliza: protector solar de día', null, false),
  ('Mandelic Acid', 'Ácido mandélico (AHA)', array['Exfoliante']::text[], null, '5-10% a pH 3.5-4', 'AHA de molécula grande: penetra más lento y es más suave. Se elige para piel sensible o con manchas leves.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Fotosensibiliza: protector solar de día', null, false),
  ('Azelaic Acid', 'Ácido azelaico', array['Antimicrobiano', 'Aclarante', 'Antiinflamatorio']::text[], null, '5-10%', 'Ácido dicarboxílico usado en acné, rosácea y manchas. Poco soluble: cuesta formularlo bien en casa.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Puede picar al inicio', null, false),
  ('Malic Acid', 'Ácido málico', array['Exfoliante', 'Regulador de pH']::text[], null, '1-5%', 'AHA de las manzanas, suave. Se usa como regulador de pH y exfoliante en conjunto con otros AHA.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Fotosensibiliza', null, false),
  ('Gluconolactone', 'Gluconolactona (PHA)', array['Exfoliante', 'Antioxidante', 'Humectante']::text[], null, '2-10%', 'Poli-hidroxiácido de molécula grande: exfolia con muy poca irritación y humecta.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
  ('Phytic Acid', 'Ácido fítico', array['Quelante', 'Antioxidante', 'Exfoliante']::text[], null, '0.1-2%', 'Se extrae de semillas y salvado. Quelante y antioxidante suave; se usa en peelings con AHA.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
  ('Kojic Acid', 'Ácido kójico', array['Despigmentante']::text[], null, '1-2%', 'Inhibe la tirosinasa y aclara manchas. Inestable a luz y calor.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Puede sensibilizar. Está regulado en varios países: revisa tu normativa', null, false),
  ('Alpha-Arbutin', 'Alfa-arbutina', array['Despigmentante', 'Aclarante']::text[], null, '0.5-2% a pH 5-7', 'Inhibe la tirosinasa, la enzima que fabrica melanina: aclara manchas de forma gradual.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Se degrada con calor y pH muy ácido', null, false),
  ('Tranexamic Acid', 'Ácido tranexámico', array['Despigmentante', 'Aclarante']::text[], null, '2-5%', 'Aminoácido sintético usado en melasma y manchas. Actúa sobre la vía plasmina-melanocito.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
  ('Caffeine', 'Cafeína', array['Descongestionante', 'Antioxidante', 'Estimulante']::text[], null, '0.5-3% en la fase acuosa caliente', 'Alcaloide hidrosoluble. Sobre la piel actúa como antioxidante y vasoconstrictor leve: descongestiona y da efecto tensor pasajero. En cuero cabelludo hay estudios que muestran que prolonga la fase anágena.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Sobre ~3% puede cristalizar al enfriar. El efecto reafirmante duradero no está bien demostrado', null, false),
  ('Ceramide NP', 'Ceramida NP', array['Acondicionador de piel', 'Regenerador']::text[], null, '0.1-1%', 'Lípido que forma el "cemento" de la barrera cutánea. Al aplicarlo repone lo que la piel pierde con la sequedad o la irritación.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Se funde en la fase oleosa', null, false),
