  ('Resveratrol', 'Resveratrol', array['Antioxidante']::text[], null, '0.1-1%', 'Polifenol de uvas y otras plantas. Antioxidante potente en laboratorio; inestable a luz y aire.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Frasco oscuro', null, false),
  ('Ferulic Acid', 'Ácido ferúlico', array['Antioxidante', 'Estabilizante']::text[], null, '0.5-1%', 'Antioxidante de las paredes celulares de cereales. Potencia y estabiliza la vitamina C y la E.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Poco soluble: disolver en un solvente adecuado', null, false),
  ('Zinc PCA', 'PCA de zinc', array['Seborregulador', 'Antimicrobiano']::text[], null, '0.5-2%', 'Sal de zinc del PCA. Se usa para regular el sebo y reducir el brillo en piel grasa.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
  ('Hydrolyzed Wheat Protein', 'Proteína hidrolizada de trigo', array['Acondicionador capilar', 'Humectante', 'Formador de película']::text[], null, '1-5%', 'Se deposita en la cutícula del cabello, rellena daños y da brillo y resistencia. En piel forma una película hidratante.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Evitar si hay alergia al gluten o al trigo', null, false),
  ('Hydrolyzed Silk', 'Seda hidrolizada', array['Acondicionador capilar', 'Humectante']::text[], null, '0.5-3%', 'Péptidos de seda que dan suavidad y brillo al cabello y a la piel.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'No es vegana', null, false),
  ('Hydrolyzed Collagen', 'Colágeno hidrolizado', array['Humectante', 'Formador de película']::text[], null, '1-5%', 'Péptidos de colágeno animal, humectantes y formadores de película. No reemplazan el colágeno de la piel.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Origen animal', null, false),
  ('Hydrolyzed Oat Protein', 'Proteína hidrolizada de avena', array['Acondicionador capilar', 'Calmante']::text[], null, '1-5%', 'Péptidos de avena, calmantes e hidratantes. Alternativa vegetal a las proteínas de seda o trigo.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
