  ('Bisabolol', 'Bisabolol', array['Calmante', 'Antiinflamatorio']::text[], null, '0.1-1%', 'Alcohol sesquiterpénico de la manzanilla o del árbol candeia. Su acción calmante está bien descrita en estudios de laboratorio; es el activo típico de los productos para piel sensible.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Liposoluble: va en la fase oleosa o en frío', null, false),
  ('Madecassoside', 'Madecasósido', array['Cicatrizante', 'Calmante', 'Regenerador']::text[], null, '0.1-1%', 'Triterpeno de la centella asiática. Calma y favorece la reparación de la piel.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
  ('Asiaticoside', 'Asiaticósido', array['Cicatrizante', 'Regenerador']::text[], null, '0.1-1%', 'Triterpeno de la centella asiática. Estimula la reparación de la piel; estudiado en cicatrización.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
  ('Dipotassium Glycyrrhizate', 'Glicirrizinato dipotásico', array['Calmante', 'Antiinflamatorio']::text[], null, '0.1-1%', 'Sal del ácido glicirrícico del regaliz. Calma y reduce el enrojecimiento.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', null, null, false),
