  ('Lactobacillus Ferment', 'Fermento de lactobacilos', array['Acondicionador de piel', 'Antimicrobiano']::text[], null, '1-5%', 'Filtrado de bacterias lácticas. Se usa por su efecto sobre el equilibrio de la microbiota de la piel.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Necesita conservante', null, false),
  ('Avena Sativa Kernel Flour', 'Avena coloidal', array['Calmante', 'Humectante', 'Protector']::text[], null, '1-2% en productos que se dejan; 10-30% en mascarillas y baños', 'Avena molida muy fina, con betaglucanos, lípidos y proteínas. Forma una capa protectora que calma la piel irritada o con picazón.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'En productos con agua se contamina fácil: necesita conservante', null, false),
  ('Propolis Extract', 'Propóleo (extracto)', array['Antimicrobiano', 'Antioxidante']::text[], null, '0.5-2% como tintura', 'Resina que las abejas elaboran con brotes de plantas. Tiene flavonoides y actividad antimicrobiana y antioxidante descritas en laboratorio.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Alérgeno conocido en personas sensibles a las abejas o a los bálsamos. Prueba de parche', null, false),
  ('Royal Jelly Extract', 'Jalea real', array['Humectante', 'Nutritivo']::text[], null, '0.5-2%', 'Secreción de las abejas obreras. Aporta proteínas y azúcares; se usa en cremas nutritivas.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Activos cosméticos', 'Alérgeno en personas sensibles a los productos de las abejas', null, false),
