  ('Sodium Benzoate', 'Benzoato de sodio', array['Conservante']::text[], 'UE: 0.5% (como ácido) en productos que se dejan; 2.5% en los que se enjuagan', '0.3-0.5%; requiere pH menor de 5', 'Sal del ácido benzoico. Actúa solo con el pH ácido, y funciona mejor contra hongos y levaduras.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Conservantes, antioxidantes y pH', 'Combinar con sorbato de potasio para ampliar el espectro', null, false),
  ('Potassium Sorbate', 'Sorbato de potasio', array['Conservante']::text[], 'UE: máx. 0.6% (como ácido sórbico)', '0.3-0.6%; requiere pH menor de 6', 'Conservante que actúa sobre todo contra hongos y levaduras. Suele combinarse con el benzoato.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Conservantes, antioxidantes y pH', null, null, false),
