  ('Citric Acid', 'Ácido cítrico', array['Regulador de pH', 'Quelante']::text[], null, '0.1-0.5%', 'Ajusta el pH hacia abajo y actúa como quelante suave que protege el producto del enranciamiento.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Conservantes, antioxidantes y pH', 'Disolver en agua antes de agregar', null, false),
  ('Sodium Citrate', 'Citrato de sodio', array['Regulador de pH', 'Quelante']::text[], null, '0.1-1%', 'Sal del ácido cítrico. Con el ácido cítrico forma un tampón que estabiliza el pH.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Conservantes, antioxidantes y pH', null, null, false),
  ('Sodium Hydroxide', 'Hidróxido de sodio (soda cáustica)', array['Regulador de pH']::text[], null, 'Gotas en solución diluida', 'Base fuerte. En cosmética se usa en solución diluida (por ejemplo al 10%) para subir el pH, y en pocas gotas. También es el álcali de la saponificación.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Conservantes, antioxidantes y pH', 'CORROSIVO: guantes y gafas; añadir siempre la soda al agua, nunca al revés', null, false),
  ('Potassium Hydroxide', 'Hidróxido de potasio', array['Regulador de pH']::text[], null, 'Según la receta', 'Base fuerte, equivalente al hidróxido de sodio. Se usa para jabones blandos o líquidos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Conservantes, antioxidantes y pH', 'CORROSIVO: guantes y gafas', null, false),
  ('Sodium Bicarbonate', 'Bicarbonato de sodio', array['Regulador de pH', 'Desodorante', 'Abrasivo suave']::text[], null, '1-10%', 'Base débil (pH ~8.3). Neutraliza olores y se usa como abrasivo suave.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Conservantes, antioxidantes y pH', 'Alcaliniza: irrita la piel en uso frecuente, sobre todo axilas y rostro', null, false),
  ('Procide PF130', 'Procide PF130 (nombre comercial)', array['Quelante', 'Potenciador de conservante']::text[], null, 'Según la ficha del proveedor', 'Producto comercial que aparece en tu inventario como quelante o refuerzo del conservante. Su composición no está verificada aquí.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Conservantes, antioxidantes y pH', 'Revisa la ficha técnica del proveedor antes de usarlo', null, false),
  ('Arginine', 'Arginina', array['Regulador de pH']::text[], null, '0.1-1%', 'Aminoácido básico que se usa para neutralizar ácidos en geles y subir el pH con suavidad.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Conservantes, antioxidantes y pH', null, null, false),
  ('Behentrimonium Methosulfate', 'BTMS (metosulfato de behentrimonio)', array['Emulsionante', 'Acondicionador capilar']::text[], null, '3-6% en acondicionadores líquidos; 40-60% en sólidos', 'Emulsionante catiónico y acondicionador. Se une a la carga negativa del cabello dañado, suaviza y reduce el frizz. El BTMS-50 viene mezclado con alcohol cetílico al 50%.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', 'Incompatible con tensioactivos aniónicos (SCI, SLSA, SCS, SLS): nunca mezclar directamente', null, false),
  ('Behentrimonium Chloride', 'Cloruro de behentrimonio', array['Emulsionante', 'Acondicionador capilar']::text[], null, '2-5%', 'Emulsionante catiónico, parecido al BTMS pero en forma de cloruro. Acondicionador y desenredante.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', 'Incompatible con aniónicos. Más irritante que el BTMS', null, false),
  ('Cetrimonium Chloride', 'Cloruro de cetrimonio', array['Acondicionador capilar', 'Antiestático']::text[], null, '1-4%', 'Tensioactivo catiónico de cadena más corta que el BTMS. Acondiciona y desenreda; más ligero.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', 'Incompatible con aniónicos. Puede irritar los ojos', null, false),
  ('Stearamidopropyl Dimethylamine', 'Estearamidopropil dimetilamina', array['Emulsionante', 'Acondicionador capilar']::text[], null, '1-5%', 'Emulsionante catiónico que actúa al neutralizarse con un ácido (por ejemplo, láctico). Usado en acondicionadores.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', 'Necesita pH ácido para activarse', null, false),
  ('Cetearyl Olivate', 'Oleato de cetearilo (Olivem 1000)', array['Emulsionante']::text[], null, '3-8%', 'Emulsionante no iónico de origen vegetal (de aceite de oliva), junto con Sorbitan Olivate. Forma emulsiones aceite en agua estables, de tacto fresco.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', 'Revisa la ficha del proveedor para las proporciones', null, false),
  ('Sorbitan Olivate', 'Olivato de sorbitán', array['Coemulsionante']::text[], null, 'Con su pareja, según la ficha', 'Parte del sistema Olivem 1000, con Cetearyl Olivate. Coemulsionante derivado del aceite de oliva.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', null, null, false),
  ('Cetearyl Alcohol (and) Polysorbate 60', 'Cera emulsionante NF', array['Emulsionante', 'Estructurante']::text[], null, '3-8% según la consistencia', 'Cera con el sistema emulsionante integrado. La vía más simple para hacer una crema aceite en agua estable: se funde con la fase oleosa y se une a la acuosa.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', 'Aparece en el rótulo como los dos ingredientes', null, false),
  ('Glyceryl Stearate SE', 'Estearato de glicerilo autoemulsionable', array['Emulsionante', 'Estructurante']::text[], null, '2-8%', 'Monoestearato de glicerilo con jabón integrado para que emulsione solo. Da cuerpo y suavidad.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', 'Sube el pH de la emulsión', null, false),
  ('Polyglyceryl-3 Methylglucose Distearate', 'Distearato de poliglicerilo-3 metilglucosa', array['Emulsionante']::text[], null, '2-5%', 'Emulsionante de origen vegetal con muy buen tacto y estabilidad. Se usa en cremas ligeras.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', null, null, false),
  ('Cetearyl Glucoside', 'Glucósido de cetearilo', array['Emulsionante', 'Estructurante']::text[], null, '3-6%', 'Emulsionante de origen vegetal (azúcares y grasas); suele venderse mezclado con alcohol cetearílico (Montanov 68). Forma cristales líquidos estables.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', null, null, false),
  ('Sucrose Stearate', 'Estearato de sacarosa', array['Emulsionante']::text[], null, '1-5%', 'Emulsionante suave derivado del azúcar y del ácido esteárico.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', null, null, false),
  ('Lecithin', 'Lecitina', array['Emulsionante', 'Humectante']::text[], null, '0.5-5%', 'Fosfolípidos de soya o girasol. Emulsionante natural nutritivo; base de los liposomas.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Emulsionantes', 'Evitar si hay alergia a la soya', null, false),
